package dk.jamesbabz.madkursus.service.applications;
import java.util.*;import dk.jamesbabz.madkursus.service.exceptions.*;import dk.jamesbabz.madkursus.service.models.*;import dk.jamesbabz.madkursus.service.ports.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @RequiredArgsConstructor public class RecipeTemplateService{private final RecipeTemplatePort port;private final RecipePort recipes;private final RecipeService recipeService;private final CurrentUserProvider currentUser;public List<RecipeTemplate> search(String query){return port.search(query);}public RecipeTemplate get(UUID id){return port.findById(id).orElseThrow(()->new ResourceNotFoundException("Recipe template",id));}public Optional<Recipe> copiedRecipe(UUID templateId){return recipes.findByUserIdAndSourceTemplateId(currentUser.currentUserId(),templateId);}@Transactional public Recipe copy(UUID id){RecipeTemplate template=get(id);if(copiedRecipe(id).isPresent())throw new ConflictException("Recipe template is already added");return recipeService.createFromTemplate(template);}}
